function translateFrench(value) {
  if (/ (gespeichert|entfernt)\.?$/.test(value)) return value.replace(/^(.*) (gespeichert|entfernt)(\.?)$/, (_, title, action, dot) => translateFrench(title) + (action === "gespeichert" ? " enregistré" : " retiré") + dot);
  if (value.includes("\n")) return value.split("\n").map(translateFrench).join("\n");
  if (value.includes(" · ")) return value.split(" · ").map(translateFrench).join(" · ");
  if (value.includes(" / ") && / — CHF /.test(value)) return value.split(" / ").map(translateFrench).join(" / ");
  if (/ — CHF /.test(value)) {
    const [label, price] = value.split(" — CHF ");
    return translateFrench(label) + " — CHF " + price.replace("Ausverkauft", "Épuisé");
  }
  if (/ view \d+$/.test(value)) return value.replace(/^(.*) view (\d+)$/, (_, title, n) => translateFrench(title) + ", vue " + n);
  const key = value.trim().replace(/\s+/g, " ");
  let translated = frenchCopy[key] || (typeof translateCatalogFrench === "function" && translateCatalogFrench(key));
  if (!translated) {
    if (key.endsWith(" | Rings made by Lari")) translated = `${translateFrench(key.slice(0, -" | Rings made by Lari".length))} | Rings made by Lari`;
    else if (/^Ring \d+/.test(key)) translated = key.replace(/^Ring /, "Bague ").replace("schmal & breit", "fine et large").replace("mittel & breit", "moyenne et large").replace(/ view (\d+)$/, ", vue $1").replace(/ gespeichert$/, " enregistré").replace(/ entfernt$/, " retiré");
    else if (/^\d+ Produkte$/.test(key)) translated = key.replace("Produkte", "produits");
    else if (/^(Details zu|Merken:|Schmuckdetail|Bild öffnen|Galeriebild) /.test(key)) {
      const match = key.match(/^(Details zu|Merken:|Schmuckdetail|Bild öffnen|Galeriebild) (.*)$/);
      const labels = {"Details zu":"Détails de", "Merken:":"Enregistrer :", Schmuckdetail:"Détail du bijou", "Bild öffnen":"Ouvrir l’image", Galeriebild:"Image de la galerie"};
      translated = `${labels[match[1]]} ${translateFrench(match[2])}`;
    } else if (key.includes(" von Rings made by Lari, handgemacht in kleinen Mengen")) {
      translated = `${translateFrench(key.split(" von Rings made by Lari,")[0])} de Rings made by Lari, fabriqués à la main en petites quantités à partir de couverts anciens argentés et d’accessoires sélectionnés.`;
    } else if (/^Ring .* (gespeichert|entfernt)$/.test(key)) {
      translated = translateFrench(key.replace(/ (gespeichert|entfernt)$/, "")) + (key.endsWith("gespeichert") ? " enregistré" : " retiré");
    }
  }
  return translated ? value.replace(value.trim(), translated) : value;
}

// Keep source strings for reversible switching; never touch form values or user input.
const frenchOriginals = new WeakMap();
const frenchAttributes = ["aria-label", "alt", "title", "placeholder", "content"];
function localizeFrenchNode(node, attribute) {
  const value = attribute ? node.getAttribute(attribute) : node.nodeValue;
  if (value === null) return;
  const records = frenchOriginals.get(node) || {};
  const id = attribute || "text";
  const previous = records[id];
  const source = previous && value === previous.translated ? previous.source : value;
  const translated = translateFrench(source);
  if (translated === value) return;
  records[id] = {source, translated};
  frenchOriginals.set(node, records);
  if (attribute) node.setAttribute(attribute, translated);
  else node.nodeValue = translated;
}
function frenchNodes(callback) {
  const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!node.parentElement.closest("script, style, textarea, [contenteditable]")) callback(node);
  }
  document.querySelectorAll("[aria-label], [alt], [title], [placeholder], meta[name=description]").forEach(element => {
    frenchAttributes.forEach(attribute => {
      if (element.hasAttribute(attribute)) callback(element, attribute);
    });
  });
}
function restoreFrench() {
  frenchObserver.disconnect();
  frenchNodes((node, attribute) => {
    const record = frenchOriginals.get(node)?.[attribute || "text"];
    const value = attribute ? node.getAttribute(attribute) : node.nodeValue;
    if (!record || value !== record.translated) return;
    if (attribute) node.setAttribute(attribute, record.source);
    else node.nodeValue = record.source;
  });
  document.querySelectorAll(".legal-copy").forEach(element => element.lang = "de");
  watchFrench();
}
function applyFrench() {
  if (typeof activeLanguage === "undefined" || activeLanguage !== "fr") return;
  frenchObserver.disconnect();
  frenchNodes(localizeFrenchNode);
  document.querySelectorAll(".legal-copy").forEach(element => element.lang = "fr");
  watchFrench();
}
// ponytail: scan these small static pages when dialogs or filters change; use keyed rendering if the UI grows.
const frenchObserver = new MutationObserver(applyFrench);
function watchFrench() {
  frenchObserver.observe(document.documentElement, {subtree:true, childList:true, characterData:true, attributes:true, attributeFilter:frenchAttributes});
}
watchFrench();
